start.filterFormula:
OR(
AND(
ISCHANGED({!$Record.Name} ),
OR( {!$Record.Record_Type_Name__c} = "Prospect CS", {!$Record.Record_Type_Name__c} = "Prospect Mkt", {!$Record.Record_Type_Name__c} = "Prospect Bloq", {!$Record.Record_Type_Name__c} = "Prospect"
)
),
AND(
ISBLANK({!$Record.Nombre_Prospect__c} ), OR( {!$Record.Record_Type_Name__c} = "Prospect CS", {!$Record.Record_Type_Name__c} = "Prospect Mkt", {!$Record.Record_Type_Name__c} = "Prospect Bloq", {!$Record.Record_Type_Name__c} = "Prospect"
))
)
